  function songDialog(existing=null){const track=existing||{},edit=!!existing;dialog(edit?'歌曲設定':'新增音樂',`<form id="musicTrackForm" class="music-form"><div class="music-form-grid"><label>媒體來源<select id="musicStorage"><option value="r2" ${track.storage==='local'||track.audioUrl?'':'selected'}>R2 雲端上傳（建議）</option><option value="local" ${track.storage==='local'?'selected':''}>只存這台裝置</option><option value="link" ${track.audioUrl?'selected':''}>使用音訊連結</option></select></label><label class="music-form-wide">音訊檔 ${edit?'（留空保留目前音檔）':'*'}<input id="musicAudioFile" type="file" accept="audio/*"></label><label class="music-form-wide">音訊網址（連結模式）<input id="musicTrackAudioUrl" type="url" value="${esc(track.audioUrl||'')}" placeholder="https:// 可直接播放的音訊檔網址"></label><label>歌曲名稱<input id="musicTrackTitle" maxlength="120" required value="${esc(track.title||'')}" placeholder="輸入歌曲名稱"></label><label>所屬專輯<select id="musicTrackAlbum">${albumOptions(track.albumId||'')}</select></label><label class="music-form-wide">歌手／演出者<select id="musicTrackArtists" multiple>${personOptions(track.artistIds||[])}</select><small>可選多位人物；可同時用文字補充外部藝名。</small></label><label class="music-form-wide">詞曲創作者<select id="musicTrackWriters" multiple>${personOptions(track.writerIds||[])}</select></label><label>其他歌手或創作者<input id="musicTrackArtistText" maxlength="180" value="${esc(track.artistExtraText||(!track.artistIds?.length?track.artistText||'':''))}" placeholder="可填人物卡以外的姓名"></label><label>單曲封面（選填）<input id="musicTrackCover" type="file" accept="image/*"></label><label class="music-form-wide">單曲封面網址（選填）<input id="musicTrackCoverUrl" type="url" value="${esc(track.coverUrl||'')}" placeholder="https://..."></label><label>MV 影片（選填）<input id="musicTrackVideo" type="file" accept="video/*"></label><label>MV 網址（選填）<input id="musicTrackVideoUrl" type="url" value="${esc(track.videoUrl||'')}" placeholder="https://..."></label><label class="music-form-wide">MV 所屬企劃（選填）<input id="musicVideoProject" list="musicVideoProjectOptions" maxlength="80" value="${esc(track.videoProject||'')}" placeholder="例如：現代大學生 Paro"><datalist id="musicVideoProjectOptions">${[...new Set(tracks().map(row=>row.videoProject).filter(Boolean))].map(project=>`<option value="${esc(project)}">`).join('')}</datalist><small>MV 庫會依此分類；相同企劃可以重複使用名稱。</small></label><label class="music-form-wide">手動主題漸層色（選填）<span class="music-colors"><input id="musicTrackColorA" type="color" value="${esc(track.themeColors?.[0]||'#bf8c6d')}"><input id="musicTrackColorB" type="color" value="${esc(track.themeColors?.[1]||'#8875b0')}"><small>沒有單曲或專輯封面時，會預設使用第一位歌手的主題色。</small></span><span><input id="musicTrackThemeManual" type="checkbox" ${track.themeManual?'checked':''}> 手動使用這組主題色</span></label><label class="music-form-wide">原文 LRC 歌詞（選填）<input id="musicOriginalLrcFile" type="file" accept=".lrc,.txt,text/plain"><textarea id="musicOriginalLrc" rows="5" placeholder="[00:12.30]第一句歌詞\n[00:16.20]第二句歌詞">${esc(track.lrcOriginal||'')}</textarea></label><label class="music-form-wide">譯文 LRC 歌詞（選填）<input id="musicTranslationLrcFile" type="file" accept=".lrc,.txt,text/plain"><textarea id="musicTranslationLrc" rows="4" placeholder="可與原文逐行對應">${esc(track.lrcTranslation||'')}</textarea></label><label class="music-form-wide">一般歌詞（選填，不帶滾動）<input id="musicPlainLyricsFile" type="file" accept=".txt,text/plain"><textarea id="musicPlainLyrics" rows="4" placeholder="純文字歌詞">${esc(track.plainLyrics||'')}</textarea></label></div></form>`,`<button class="music-secondary" data-action="dialog-close">取消</button><button class="music-primary" data-action="save-track" data-id="${esc(track.id||'')}"><i class="fa-solid fa-check"></i> 儲存歌曲</button>`);}
  function albumDialog(existing=null){const album=existing||{};dialog(existing?'編輯專輯':'建立專輯',`<form id="musicAlbumForm" class="music-form"><label>專輯名稱<input id="musicAlbumTitle" maxlength="100" required value="${esc(album.title||'')}" placeholder="輸入專輯名稱"></label><label>專輯歌手<select id="musicAlbumArtists" multiple>${personOptions(album.artistIds||[])}</select></label><label class="music-form-wide">專輯介紹<textarea id="musicAlbumDescription" rows="4" placeholder="寫下專輯簡介">${esc(album.description||'')}</textarea></label><label>專輯封面<input id="musicAlbumCover" type="file" accept="image/*"></label><label>封面網址<input id="musicAlbumCoverUrl" type="url" value="${esc(album.coverUrl||'')}" placeholder="https://..."></label><label>手動主題漸層<input id="musicAlbumColorA" type="color" value="${esc(album.themeColors?.[0]||'#bf8c6d')}"><input id="musicAlbumColorB" type="color" value="${esc(album.themeColors?.[1]||'#8875b0')}"><span><input id="musicAlbumThemeManual" type="checkbox" ${album.themeManual?'checked':''}> 手動使用這組主題色</span><small>上傳封面會自動取樣；沒有封面且未勾選時，專輯使用第一位歌手的主題色。</small></label></form>`,`<button class="music-secondary" data-action="dialog-close">取消</button><button class="music-primary" data-action="save-album" data-id="${esc(album.id||'')}">儲存專輯</button>`);}
