  function handleInput(event){if(event.target.id==='musicSearch'){query=event.target.value;clearTimeout(searchDebounce);searchDebounce=setTimeout(()=>{if(['songs','playlist'].includes(view))render();},130);}if(event.target.id==='musicSeek'&&audio&&Number.isFinite(audio.duration))audio.currentTime=audio.duration*Number(event.target.value)/1000;if(event.target.id==='musicVolume'&&audio)audio.volume=Number(event.target.value);}
