  const saveTrackWithoutPendingFiles=saveTrack;
  saveTrack=async function(id){try{await pendingLyricReads;}catch(error){pendingLyricReads=Promise.resolve();return message(`歌詞檔讀取失敗：${error.message}`,true);}try{const localOnly=$('musicStorage')?.value==='local',result=await saveTrackWithoutPendingFiles(id);if(localOnly&&id&&$('musicDialog')?.hidden){const rows=musicMetadataRows(),index=rows.findIndex(row=>row.id===id);if(index>=0){rows.splice(index,1);try{saveStateToLocalStorage();}catch(error){message(`本機歌曲已更新，但舊雲端索引尚未清除：${error.message}`,true);}}}return result;}catch(error){return message(`歌曲未能儲存：${error.message}`,true);}};
  const renderPlayerWithoutTools=renderPlayer;
  renderPlayer=function(){const result=renderPlayerWithoutTools();const extra=$('ocMusicApp')?.querySelector('.music-player-extra');if(extra&&!extra.querySelector('[data-action="toggle-player-lyrics"]'))extra.insertAdjacentHTML('afterbegin','<button type="button" data-action="toggle-player-lyrics" aria-label="切換歌詞畫面" title="歌詞"><i class="fa-solid fa-closed-captioning"></i></button>');const track=currentTrack(),info=$('ocMusicApp')?.querySelector('.music-full-player-info');if(track&&info&&!info.querySelector('.music-edit-lyrics'))info.insertAdjacentHTML('beforeend',`<button type="button" class="music-edit-lyrics" data-action="edit-track" data-id="${esc(track.id)}"><i class="fa-solid fa-pen"></i> 編輯歌曲與歌詞</button>`);return result;};
  const renderPlayerBeforeArtistRefresh=renderPlayer;
  renderPlayer=function(){const result=renderPlayerBeforeArtistRefresh();const label=displayArtist(currentTrack());const now=$('musicNowMeta')?.querySelector('span');if(now)now.textContent=label||'你的音樂空間';if($('musicPlayerArtist'))$('musicPlayerArtist').textContent=label||'SONORA 音樂媒體';return result;};
