  render=function(){renderBeforeArtistRefresh();const host=$('ocMusicApp');if(!host||host.hidden)return;host.querySelectorAll('.music-track-row').forEach(row=>{const track=tracks().find(item=>item.id===row.dataset.track),label=row.querySelector('.music-track-title small');if(label&&track)label.textContent=displayArtist(track)||'未知演出者';});const track=currentTrack();host.querySelectorAll('.music-full-player-info p,.music-lyrics-scene-head small').forEach(label=>{if(track)label.textContent=label.matches('p')?`${displayArtist(track)||'未知歌手'} · ${track.albumTitle||'單曲'}`:displayArtist(track);});const picker=$('musicArtistFilters');if(picker){const singerIds=new Set(tracks().flatMap(track=>track.artistIds||[]).map(String));picker.querySelectorAll('[data-action="person-filter"]').forEach(button=>{if(!singerIds.has(button.dataset.id))button.remove();});if(!picker.querySelector('[data-action="person-filter"]'))picker.innerHTML='<small class="music-muted">關聯歌手後會出現在這裡</small>';}const modal=$('musicDialog');if(modal&&!modal._mvObserver){modal._mvObserver=new MutationObserver(()=>{if(modal.hidden)modal.querySelectorAll('video').forEach(video=>{video.pause();video.removeAttribute('src');video.load();});});modal._mvObserver.observe(modal,{attributes:true,attributeFilter:['hidden']});}};
  async function deleteTrackCompletely(id){
    const track=tracks().find(row=>row.id===id);if(!track)return;
    if(!confirm(`刪除「${track.title}」？歌曲、歌詞、本機檔案及這首歌專用的 R2 音訊／封面／MV 都會移除，無法復原。`))return;
    const rows=musicMetadataRows(),index=rows.findIndex(row=>row.id===id),previous=index>=0?rows[index]:null;
    if(index>=0)rows.splice(index,1);
    try{saveStateToLocalStorage();}catch(error){if(index>=0)rows.splice(index,0,previous);return message(`無法保存刪除結果：${error.message}`,true);}
    try{await remove(id);}catch(error){if(index>=0){rows.splice(index,0,previous);try{saveStateToLocalStorage();}catch{}}return message(`無法刪除本機歌曲：${error.message}`,true);}
    if(activeTrackId===id){audio?.pause();if(audio){audio.removeAttribute('src');audio.load();}activeTrackId='';playerLyricsMode=false;}
    queue=queue.filter(trackId=>trackId!==id);queueIndex=Math.min(queueIndex,queue.length-1);
    let playlistFailures=0;for(const playlist of playlists().filter(row=>(row.trackIds||[]).includes(id))){const updated={...playlist,trackIds:playlist.trackIds.filter(trackId=>trackId!==id)};try{await put(updated);mirror(updated);items=items.map(row=>row.id===playlist.id?updated:row);}catch{playlistFailures++;}}
    items=items.filter(row=>row.id!==id);$('musicDialog').hidden=true;render();
    const remoteIds=[...new Set([track.remoteAudioId,track.remoteCoverId,track.remoteVideoId].filter(Boolean))].filter(remoteId=>!tracks().some(other=>other.id!==id&&[other.remoteAudioId,other.remoteCoverId,other.remoteVideoId].includes(remoteId)));
    if(remoteIds.length){const results=await Promise.allSettled(remoteIds.map(remoteId=>window.OCFeatures.deleteMusicMedia(remoteId)));const failed=remoteIds.filter((_,position)=>results[position].status==='rejected');remoteIds.forEach(remoteId=>remoteUrls.delete(remoteId));if(failed.length)return message(`歌曲已刪除，但 ${failed.length} 個 R2 檔案未能移除：${failed.join('、')}。請確認 Worker 連線後手動清理。`,true);}
    message(playlistFailures?`歌曲已刪除，但 ${playlistFailures} 份播放清單未能更新，請重新開啟音樂庫確認。`:'歌曲與其專用 R2 檔案已刪除。',playlistFailures>0);
  }
  const handleClickWithoutCompleteDelete=handleClick;
  handleClick=function(event){const button=event.target.closest('[data-action],[data-view]');if(button?.dataset.action==='delete-track'){event.preventDefault();deleteTrackCompletely(button.dataset.id);return;}if(button?.dataset.view||['close','home','dialog-close','video-project-filter'].includes(button?.dataset.action))$('ocMusicApp')?.querySelectorAll('video').forEach(video=>video.pause());return handleClickWithoutCompleteDelete(event);};
  const closeBeforeMvStop=close;
  close=function(fromBack=false){$('ocMusicApp')?.querySelectorAll('video').forEach(video=>video.pause());return closeBeforeMvStop(fromBack);};
  const backBeforeMvStop=handleBack;
